import{_ as s,l as B,o as e,c as i,v as t,p as d,x as o,d as l,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"BTB 与返回栈","description":"","frontmatter":{"title":"BTB 与返回栈","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/btb-ras.md","filePath":"cs/btb-ras.md","lastUpdated":1789023840000}'),p={name:"cs/btb-ras.md"};function A(E,a,h,T,_,m){const r=B("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="btb-与返回栈" tabindex="-1">BTB 与返回栈 <a class="header-anchor" href="#btb-与返回栈" aria-label="Permalink to &quot;BTB 与返回栈&quot;">​</a></h1><div class="epigraph"><p>方向猜对还不够：间接跳转的目标每次可能不同，返回地址却几乎总是配对的那一次调用。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach 整理</footer></div><p><a href="/cs/control-hazard-predict">上一课</a>让 IF 按一位计数器或静态规则猜方向，核对失败则冲刷。条件分支的目标是 PC 加立即数，算出来即可。本课不重讲饱和计数器。缺口是：间接跳转与 <code>ret</code> 的<strong>目标地址</strong>在译码前未知，猜方向帮不上忙。本课只交出分支目标缓冲（BTB）与返回地址栈（RAS）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>jalr</code>、虚函数、<code>switch</code> 跳表：下一 PC 来自寄存器，五级里要到 ID 甚至 EX 才有值。若 IF 只准备「成功/失败」两位，仍不知道往哪取。返回指令的目标倒是历史：对应 <code>jal</code> 当时的 PC+4。缺口不是更宽的条件比较，而是<strong>用 PC 索引一张目标表，并用栈专门记返回地址</strong>。</p><p>上一课明确不把间接跳转预测表铺开。本课补上这一块，仍不引入两级模式历史。</p><p><span class="marginnote">BTB 命中且预测成功，IF 下一拍就能从目标取指，不必等 ALU 算地址。RAS 深度有限，递归过深会溢出，只能当提示。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>BTB：按取指 PC 索引（可组相联），条目存标签、预测目标、可选一位有效。命中则用存下的目标当下一 PC；EX 核对，错则冲刷并更新该条目。未命中则按顺序取指或按方向预测走立即数目标。</p><p>RAS：<code>jal</code>/<code>jalr</code> 用作调用时把返回地址压栈；译码到返回时弹栈当预测目标。与 BTB 可并行：返回优先信 RAS。</p>',10)),(e(),d(c,null,{default:o(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PC%5B%22%E5%8F%96%E6%8C%87%20PC%22%5D%20--%3E%20BTB%5B%22BTB%20%E6%9F%A5%E7%9B%AE%E6%A0%87%22%5D%0A%20%20PC%20--%3E%20RAS%5B%22%E8%AF%91%E7%A0%81%E4%B8%BA%E8%BF%94%E5%9B%9E%E5%88%99%E5%BC%B9%20RAS%22%5D%0A%20%20BTB%20--%3E%20IF%5B%22IF%20%E7%94%A8%E9%A2%84%E6%B5%8B%20PC%22%5D%0A%20%20RAS%20--%3E%20IF%0A%20%20IF%20--%3E%20CHK%5B%22EX%20%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20CHK%20--%3E%7C%22%E9%94%99%22%7C%20FLUSH%5B%22%E5%86%B2%E5%88%B7%E5%B9%B6%E6%9B%B4%E6%96%B0%20BTB%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>控制冒险的损失拍数里，「目标未知」与「方向未知」是两项。BTB 把前者从「等 EX」降到「等 BTB SRAM」，命中时与条件预测叠用。RAS 利用调用/返回的 LIFO，准确率通常高于把返回当成普通间接跳转塞进 BTB——BTB 会被不同调用点别名污染。</p><p>BTB 本身是预测器状态，不是 ISA 寄存器。上下文切换不必保存；冷 BTB 只让误预测暂时升高。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入竞赛预测、不引入间接跳转的完整历史（ITTAGE 一类）。特权态 <code>eret</code> 的目标来自 CSR，不走用户 RAS。异常冲刷时 RAS 可能失配，实现可选择恢复或清空；精确性仍由<a href="/cs/pipeline-exception">流水线异常</a>的提交点保证，预测结构可以错。</p><p>后课默认：IF 的下一 PC 来自顺序、条件立即数、BTB 或 RAS。方向仍可用简单计数器；更准的相关预测是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BTB 缓存间接/分支目标，让 IF 不必等算出地址。</li><li>RAS 按调用栈弹返回地址，比把 <code>ret</code> 塞进 BTB 更稳。</li><li>两级与锦标赛预测是后课的缺口。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> 分支目标缓冲与返回栈。</li></ul>',8))])}const b=s(p,[["render",A]]);export{S as __pageData,b as default};
